import { Gesture, GestureDetector } from 'react-native-gesture-handler'
import { ProjectScreen, type ProjectScreenProps } from './ProjectScreen'
import Animated, {
	interpolate,
	runOnJS,
	useAnimatedStyle,
	useSharedValue,
	withTiming
} from 'react-native-reanimated'
import * as Haptics from 'expo-haptics'
import { defineStyles } from '@/utils/defineStyles'
import { useSetThreadId } from '../chat/store/threadStore'

export const ProjectScreenContainer = ({
	onClose,
	...screenProps
}: { onClose: () => void } & ProjectScreenProps) => {
	const offsetX = useSharedValue(0)
	const offsetY = useSharedValue(0)
	const xPosition = useSharedValue(0)
	const yPosition = useSharedValue(0)
	const opacity = useSharedValue(1)

	const setThreadId = useSetThreadId()

	const pan = Gesture.Pan()
		.activeOffsetY(10)
		.onChange((event) => {
			xPosition.set(event.translationX)
			if (yPosition.get() <= 20 && event.translationY / 5 > 20) {
				runOnJS(Haptics.impactAsync)(Haptics.ImpactFeedbackStyle.Medium)
			}
			if (yPosition.get() > 20 && event.translationY / 5 <= 20) {
				runOnJS(Haptics.impactAsync)(Haptics.ImpactFeedbackStyle.Medium)
			}
			yPosition.set(event.translationY / 5)
			offsetY.set(event.translationY)
			offsetX.set(event.translationX)
		})
		.onFinalize(() => {
			if (yPosition.get() > 20) {
				runOnJS(setThreadId)(null)
				yPosition.set(
					withTiming(200, { duration: 300 }, () => {
						runOnJS(onClose)()
					})
				)
				opacity.set(withTiming(0, { duration: 300 }))
			} else {
				xPosition.set(withTiming(0, { duration: 200 }))
				yPosition.set(withTiming(0, { duration: 200 }))
				offsetY.set(0)
				offsetX.set(0)
			}
		})

	const animatedStyle = useAnimatedStyle(() => ({
		opacity: opacity.get(),
		transform: [
			{ translateX: xPosition.get() },
			{ translateY: yPosition.get() },
			{
				scale: interpolate(yPosition.get(), [0, 10], [1, 0.95], {
					extrapolateLeft: 'clamp'
				})
			}
		]
	}))

	return (
		<Animated.View style={[styles.container, animatedStyle]}>
			<GestureDetector gesture={pan}>
				<ProjectScreen {...screenProps} />
			</GestureDetector>
		</Animated.View>
	)
}

const styles = defineStyles({
	container: {
		flex: 1
	}
})
